class LazyLoader{constructor(options={}){this.options={root:options.root||null,rootMargin:options.rootMargin||'50px',threshold:options.threshold||0.01,loadingClass:options.loadingClass||'lazy-loading',loadedClass:options.loadedClass||'lazy-loaded',errorClass:options.errorClass||'lazy-error'};this.observer=null;this.init();}
init(){if(!('IntersectionObserver'in window)){console.warn('Intersection Observer not supported, loading all images immediately');this.loadAllImages();return;}
this.observer=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){this.loadImage(entry.target);this.observer.unobserve(entry.target);}});},this.options);this.observeImages();}
observeImages(){const images=document.querySelectorAll('img[data-src], [data-bg]');images.forEach(img=>{this.observer.observe(img);});}
loadImage(element){const isImg=element.tagName==='IMG';const src=element.dataset.src||element.dataset.bg;if(!src)return;element.classList.add(this.options.loadingClass);if(isImg){const img=new Image();img.onload=()=>{element.src=src;element.classList.remove(this.options.loadingClass);element.classList.add(this.options.loadedClass);element.removeAttribute('data-src');};img.onerror=()=>{element.classList.remove(this.options.loadingClass);element.classList.add(this.options.errorClass);element.src='/images/placeholder.png';element.alt='圖片載入失敗';};img.src=src;}else{const img=new Image();img.onload=()=>{element.style.backgroundImage=`url('${src}')`;element.classList.remove(this.options.loadingClass);element.classList.add(this.options.loadedClass);element.removeAttribute('data-bg');};img.onerror=()=>{element.classList.remove(this.options.loadingClass);element.classList.add(this.options.errorClass);};img.src=src;}}
loadAllImages(){const images=document.querySelectorAll('img[data-src], [data-bg]');images.forEach(img=>this.loadImage(img));}
observe(element){if(this.observer){this.observer.observe(element);}else{this.loadImage(element);}}
disconnect(){if(this.observer){this.observer.disconnect();}}}
let lazyLoader=null;function initLazyLoad(){lazyLoader=new LazyLoader({rootMargin:'100px',threshold:0.01});}
function lazyLoadImage(element){if(lazyLoader){lazyLoader.observe(element);}}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initLazyLoad);}else{initLazyLoad();}
window.lazyLoadImage=lazyLoadImage;